{% extends "base.html" %}

{% block title %}@note.com レポートURL一覧{% endblock %}

{% block content %}
    <div class="container py-5">
      <div class="d-flex align-items-center justify-content-center mb-4">
        <h1 class="mb-0 me-3">note.com<br>公開レポート一覧</h1>
        <!-- TEMPORARY WORKAROUND: Hardcoded URL for static asset. See comment on apiUrl for full context. -->
        <img src="/past_exam_reports/static/admin_icon.png" alt="Admin Avatar" class="rounded-circle" style="width: 80px; height: 80px;">
      </div>
      <p class="text-center text-muted mb-5">各学校のnote.comで公開されている過去問分析レポートへのリンクです。</p>

      <!-- 絞り込みフォーム -->
      <div class="mb-4 p-4 bg-light rounded-3">
        <div class="row g-3 align-items-end">
          <!-- 学校名検索 -->
          <div class="col-md-6">
            <label for="schoolSearchInput" class="form-label">学校名</label>
            <input type="text" id="schoolSearchInput" class="form-control form-control-lg" placeholder="学校名（一部でもOK）で検索...">
          </div>
          <!-- 教科プルダウン -->
          <div class="col-md-6">
            <label for="subjectSelect" class="form-label">教科</label>
            <select name="subject" id="subjectSelect" class="form-select form-select-lg">
              <option value="">すべての教科</option>
              {% for subject in subjects %}
                <option value="{{ subject }}" {% if subject == selected_subject %}selected{% endif %}>{{ subject }}</option>
              {% endfor %}
            </select>
          </div>
        </div>
      </div>

      <!-- 表示件数 -->
      <div class="d-flex justify-content-between align-items-center mb-3">
        <p class="mb-0 text-muted">該当件数: <span id="schoolCount">{{ school_count }}</span>件</p>
      </div>

      <div id="schoolsListContainer">
        {% if schools %}
          <div class="row row-cols-1 g-4" id="schoolsList">
            {% for school in schools %}
            <div class="col school-item">
              <div class="card shadow-sm h-100">
                <div class="card-body">
                  <div class="row align-items-center g-2">
                    <div class="col-12 col-md-auto flex-grow-1">
                      <h5 class="card-title mb-0">{{ school.name }}</h5>
                    </div>
                    {% if school.reports %}
                      <div class="col-12 col-md-auto">
                        <div class="d-flex flex-wrap gap-2 justify-content-md-end">
                          {% for report in school.reports %}
                            {% set is_disabled = not report.note_url %}
                            <a href="{{ report.note_url if not is_disabled else '#' }}"
                               target="_blank"
                               rel="noopener noreferrer"
                               class="btn btn-sm {% if is_disabled %}btn-outline-secondary disabled{% else %}btn-outline-primary{% endif %}"
                               {% if is_disabled %}aria-disabled="true"{% endif %}>
                              <i class="fas fa-file-alt me-1"></i> {{ report.subject }}
                            </a>
                          {% endfor %}
                        </div>
                      </div>
                    {% else %}
                      <div class="col-12 col-md-auto">
                        <p class="card-text text-muted mb-0">この学校のレポートはまだありません。</p>
                      </div>
                    {% endif %}
                  </div>
                </div>
              </div>
            </div>
            {% endfor %}
          </div>
        {% else %}
          <div class="alert alert-info text-center">
            該当するレポートはありません。
          </div>
        {% endif %}
      </div>
    </div>

    <!-- Disclaimer Modal -->
    <div class="modal fade" id="disclaimerModal" tabindex="-1" aria-labelledby="disclaimerModalLabel" aria-hidden="true">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title" id="disclaimerModalLabel">免責事項</h5>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div class="modal-body">
            <!-- Content will be loaded from /static/disclaimer.html -->
          </div>
          <div class="modal-footer">
            <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">閉じる</button>
            <button type="button" id="agreeButton" class="btn btn-primary">同意して続きを読む</button>
          </div>
        </div>
      </div>
    </div>
{% endblock %}

{% block scripts %}
<script>
  const schoolSearchInput = document.getElementById("schoolSearchInput");
  const subjectSelect = document.getElementById("subjectSelect");
  const schoolCountSpan = document.getElementById("schoolCount");
  const schoolsListContainer = document.getElementById("schoolsListContainer");
  let isComposing = false;

  // --- 関数定義 ---

  /**
   * 学校リストのHTMLを生成し、画面を更新する
   * @param {Array} schools - 表示する学校の配列
   */
  function updateSchoolList(schools) {
    schoolsListContainer.innerHTML = ''; // コンテナをクリア

    if (!schools || schools.length === 0) {
      schoolsListContainer.innerHTML = '<div class="alert alert-info text-center">該当するレポートはありません。</div>';
      schoolCountSpan.textContent = 0;
      return;
    }

    const listWrapper = document.createElement('div');
    listWrapper.className = 'row row-cols-1 g-4';
    listWrapper.id = 'schoolsList';

    schools.forEach(school => {
      const reportsHtml = school.reports.map(report => {
        const isDisabled = !report.note_url;
        const btnClass = isDisabled ? 'btn-outline-secondary disabled' : 'btn-outline-primary';
        const disabledAttrs = isDisabled ? 'aria-disabled="true"' : '';
        const href = isDisabled ? '#' : 'javascript:void(0)';
        const modalAttrs = isDisabled ? '' : `data-bs-toggle="modal" data-bs-target="#disclaimerModal" data-note-url="${report.note_url}"`;

        return `
          <a href="${href}" class="btn btn-sm ${btnClass}" ${disabledAttrs} ${modalAttrs}>
            <i class="fas fa-file-alt me-1"></i> ${report.subject}
          </a>
        `;
      }).join('');

      const schoolItem = document.createElement('div');
      schoolItem.className = 'col school-item';
      schoolItem.innerHTML = `
        <div class="card shadow-sm h-100">
          <div class="card-body">
            <div class="row align-items-center g-2">
              <div class="col-12 col-md-auto flex-grow-1">
                <h5 class="card-title mb-0">${school.name}</h5>
              </div>
              <div class="col-12 col-md-auto">
                <div class="d-flex flex-wrap gap-2 justify-content-md-end">
                  ${reportsHtml}
                </div>
              </div>
            </div>
          </div>
        </div>
      `;
      listWrapper.appendChild(schoolItem);
    });

    schoolsListContainer.appendChild(listWrapper);
    schoolCountSpan.textContent = schools.length;

    // 学校名でのインクリメンタル検索を再適用
    applySchoolNameFilter();
  }

  /**
   * 学校名でのインクリメンタル検索を実行する
   */
  function applySchoolNameFilter() {
    if (isComposing) return; // 変換中は処理しない

    let filter = schoolSearchInput.value.toLowerCase();
    let items = document.querySelectorAll("#schoolsList .school-item");
    let visibleCount = 0;

    items.forEach(item => {
      let title = item.querySelector(".card-title").textContent.toLowerCase().trim();
      if (title.includes(filter)) {
        item.style.display = "";
        visibleCount++;
      } else {
        item.style.display = "none";
      }
    });
    schoolCountSpan.textContent = visibleCount;
  }

  // --- イベントリスナー ---

  // 学校名検索
  schoolSearchInput.addEventListener("input", applySchoolNameFilter);

  // 日本語入力対応
  schoolSearchInput.addEventListener("compositionstart", () => { isComposing = true; });
  schoolSearchInput.addEventListener("compositionend", () => {
    isComposing = false;
    applySchoolNameFilter();
  });

  // 教科プルダウン
  subjectSelect.addEventListener("change", function() {
    const selectedSubject = this.value;
    /*
     * TEMPORARY WORKAROUND (2025-10-08):
     * The API endpoint URL is hardcoded here instead of using Flask's url_for().
     *
     * REASON:
     * When deployed under a subpath (/past_exam_reports), the url_for('api_schools')
     * function was incorrectly generating '/api/schools' instead of the required
     * '/past_exam_reports/api/schools'. This caused the subject filter API call to fail.
     *
     * HISTORY:
     * Standard methods to resolve this (setting app.config['APPLICATION_ROOT'] and
     * using a WSGI middleware to set SCRIPT_NAME) were attempted but did not work
     * in this specific Nginx/Gunicorn environment. As a pragmatic solution to restore
     * functionality, the URL is being temporarily hardcoded.
     *
     * TODO:
     * Revisit this and implement a robust solution for subpath URL generation,
     * likely by debugging the WSGI environment interaction or refactoring to a Blueprint.
     */
    const apiUrl = `/past_exam_reports/api/schools${selectedSubject ? '?subject=' + encodeURIComponent(selectedSubject) : ''}`;

    // フェッチ中にローディング表示などをしても良い
    schoolCountSpan.textContent = '検索中...';

    fetch(apiUrl)
      .then(response => response.json())
      .then(data => {
        updateSchoolList(data.schools);
      })
      .catch(error => {
        console.error('Error fetching schools:', error);
        schoolsListContainer.innerHTML = '<div class="alert alert-danger text-center">データの取得に失敗しました。</div>';
      });
  });

  // モーダル処理
  const disclaimerModal = document.getElementById('disclaimerModal');
  if (disclaimerModal) {
    const modalBody = disclaimerModal.querySelector('.modal-body');
    const agreeButton = document.getElementById('agreeButton');

    disclaimerModal.addEventListener('show.bs.modal', function (event) {
      // Load disclaimer content
      fetch('{{ url_for('static', filename='disclaimer.html') }}')
        .then(response => response.text())
        .then(html => {
          modalBody.innerHTML = html;
        })
        .catch(error => {
          modalBody.innerHTML = '<p>免責事項の読み込みに失敗しました。</p>';
          console.error('Error fetching disclaimer:', error);
        });

      const button = event.relatedTarget;
      const noteUrl = button.getAttribute('data-note-url');
      if (agreeButton) {
        agreeButton.dataset.noteUrl = noteUrl;
      }
    });

    // 「同意して続きを読む」ボタンのクリック処理
    if (agreeButton) {
      agreeButton.addEventListener('click', () => {
        const noteUrl = agreeButton.dataset.noteUrl;
        if (noteUrl) {
          window.open(noteUrl, '_blank');
        }
        const modalInstance = bootstrap.Modal.getInstance(disclaimerModal);
        if (modalInstance) {
          modalInstance.hide();
        }
      });
    }
  }

</script>
{% endblock %}
