from app import app as application

class SubpathMiddleware:
    """
    A middleware to set the SCRIPT_NAME in the WSGI environment,
    which is used by Flask for URL generation.
    """
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        # Nginx sets the SCRIPT_NAME header, which Gunicorn makes available
        # as HTTP_X_SCRIPT_NAME.
        script_name = environ.get('HTTP_X_SCRIPT_NAME', '')
        if script_name:
            environ['SCRIPT_NAME'] = script_name
        return self.app(environ, start_response)

# Wrap the Flask app's WSGI interface with the middleware
application.wsgi_app = SubpathMiddleware(application.wsgi_app)


if __name__ == "__main__":
    application.run()


